  const src=[
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.0],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.0],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.0],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,5.0],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.5],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+4)*40,0.13,1.8,1.5],
    [200+Math.sin(t*0.7)*110,200+Math.cos(t*0.3)*70,0.05,2.4,2.5],
    [300+Math.cos(t*0.25+4)*100,30+Math.sin(t*0.85+2)*60,0.09,2.0,3.5]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    aS2+=Math.sin(d*f*1.3-t*sp*0.8+ph*0.7);
    iS2+=Math.cos(d*f*0.5+t*sp*0.4+ph*1.2);
  }
  const act=aS/10,inh=iS/10,act2=aS2/10,inh2=iS2/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.6))/3+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15+Math.sin(sx*0.08)*Math.sin(sy*0.06+t*0.3)*0.2;
