  const radial=Math.sin(dist*0.03-t*0.5)*Math.cos(ang*2+t*0.3)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+radial)*2.2);
  const reaction2=Math.tanh((act2-inh2*0.6+reaction*0.5+bg*0.2-spiral*0.3)*1.8);
  const combined=reaction*0.6+reaction2*0.4;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voro=Math.sin(sx*0.12+t*0.2)*Math.sin(sy*0.12-t*0.15)+Math.sin((sx*0.7+sy*0.7)*0.08+t*0.3)*0.5;
  const blend=combined*0.6+cell*0.2+Math.tanh(voro*0.8)*0.2;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,85],[18,85,105],[20,135,125],[60,170,120],[180,190,70],[220,170,55],[215,110,60],[180,60,55],[120,30,55],[70,18,48],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
