  const edge=Math.abs(combined)>0.65?1.12:(Math.abs(combined)>0.3?1.0:0.92);
  const pulse=1.0+Math.sin(t*0.8)*0.05;
  const total=lum*edge*pulse;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*total)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*total)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*total)|0
  ];
}
